#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def is_active(value):
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {'true', '1', 'yes', 'y', 'active'}


def money(value):
    return round(float(value) + 1e-9, 2)


manifest = load_json('assay_manifest.json')
carrier_rows = load_csv('carrier_cost.csv')
billing_rows = load_csv('billing.csv')
override_rows = load_csv('lab_overrides.csv')
template = load_json('report_template.json')

carrier_cost_by_type = {
    row['carrier_type']: float(row['carrier_cost_usd'])
    for row in carrier_rows
}

in_scope_assays = []
label_to_assay_id = {}
assay_by_id = {}
for region in manifest.get('regions', []):
    for assay in region.get('assays', []):
        if assay.get('in_scope') is True:
            in_scope_assays.append(assay)
            assay_by_id[assay['assay_id']] = assay
            labels = [assay['assay_name']] + list(assay.get('aliases', []))
            for label in labels:
                label_to_assay_id[label.strip().casefold()] = assay['assay_id']

# Latest active billing row per in-scope assay.
billing_by_assay = {}
for row in billing_rows:
    assay_id = label_to_assay_id.get(row['assay_label'].strip().casefold())
    if assay_id is None or not is_active(row.get('is_active')):
        continue
    current = billing_by_assay.get(assay_id)
    if current is None or row['effective_month'] > current['effective_month']:
        billing_by_assay[assay_id] = row

# Highest approved lab override revision per assay.
approved_override_by_assay = {}
for row in override_rows:
    if row.get('status', '').strip().lower() != 'approved':
        continue
    assay_id = row['assay_id']
    revision = int(row['revision'])
    current = approved_override_by_assay.get(assay_id)
    if current is None or revision > int(current['revision']):
        approved_override_by_assay[assay_id] = row

assay_results = []
total_small_margin = 0.0
total_bulk_margin = 0.0

for assay in sorted(in_scope_assays, key=lambda a: a['assay_id']):
    assay_id = assay['assay_id']
    billing = billing_by_assay.get(assay_id)
    if billing is None:
        raise ValueError(f'No active billing row found for in-scope assay {assay_id}')

    override = approved_override_by_assay.get(assay_id)
    if override is not None:
        active_labs = int(override['active_labs'])
    else:
        active_labs = int(assay['default_active_labs'])

    carrier_cost_usd = float(carrier_cost_by_type[assay['carrier_type']])
    payment = float(billing['payment_per_run_per_lab_usd'])
    reagent_price = float(assay['reagent_price_per_1000_tests_usd'])

    def financials(runs_per_year, tests_per_lab_per_run):
        annual_revenue = payment * active_labs * runs_per_year
        annual_reagent_cost = reagent_price * active_labs * tests_per_lab_per_run * runs_per_year / 1000.0
        annual_carrier_cost = carrier_cost_usd * active_labs * runs_per_year
        annual_margin = annual_revenue - annual_reagent_cost - annual_carrier_cost
        return {
            'runs_per_year': runs_per_year,
            'tests_per_lab_per_run': int(tests_per_lab_per_run),
            'annual_revenue_usd': money(annual_revenue),
            'annual_reagent_cost_usd': money(annual_reagent_cost),
            'annual_carrier_cost_usd': money(annual_carrier_cost),
            'annual_margin_usd': money(annual_margin),
        }

    small = financials(24, assay['tests_per_lab_per_run_small'])
    bulk = financials(12, assay['tests_per_lab_per_run_bulk'])
    diff = money(bulk['annual_margin_usd'] - small['annual_margin_usd'])

    total_small_margin += small['annual_margin_usd']
    total_bulk_margin += bulk['annual_margin_usd']

    assay_results.append({
        'assay_id': assay_id,
        'assay_name': assay['assay_name'],
        'active_labs': active_labs,
        'billing_effective_month': billing['effective_month'],
        'payment_per_run_per_lab_usd': money(payment),
        'carrier_type': assay['carrier_type'],
        'carrier_cost_usd': money(carrier_cost_usd),
        'small_kit': small,
        'bulk_kit': bulk,
        'annual_margin_difference_bulk_minus_small_usd': diff,
    })

total_small_margin = money(total_small_margin)
total_bulk_margin = money(total_bulk_margin)
total_difference = money(total_bulk_margin - total_small_margin)
absolute_difference = money(abs(total_difference))

decision = 'adopt_bulk_kit' if absolute_difference < 7000 else 'keep_small_kit'
if decision == 'adopt_bulk_kit':
    justification = (
        f'Absolute total margin difference is ${absolute_difference:,.2f}, below the '
        f'$7,000 switch threshold, so the bulk kit can be adopted.'
    )
else:
    justification = (
        f'Absolute total margin difference is ${absolute_difference:,.2f}, at or above the '
        f'$7,000 switch threshold, so the small kit should be kept.'
    )

report = {
    'metadata': template['metadata'],
    'analysis': {
        'assumptions': {
            'runs_per_year_small_kit': 24,
            'runs_per_year_bulk_kit': 12,
            'switch_threshold_usd': 7000,
            'lab_override_rule': 'highest approved revision per assay_id, else default_active_labs',
            'billing_rule': 'latest active effective_month per assay',
        },
        'assays': assay_results,
        'totals': {
            'total_small_kit_margin_usd': total_small_margin,
            'total_bulk_kit_margin_usd': total_bulk_margin,
            'total_difference_bulk_minus_small_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    },
}

with (ROOT / 'reagent_policy_report.json').open('w') as f:
    json.dump(report, f, indent=2)
    f.write('\n')

summary_lines = [
    '# Reagent Policy Summary',
    f'Total small-kit margin: ${total_small_margin:,.2f} USD',
    f'Total bulk-kit margin: ${total_bulk_margin:,.2f} USD',
    f'Absolute difference: ${absolute_difference:,.2f} USD',
    f'Decision: {decision}',
    justification,
]
with (ROOT / 'reagent_policy_summary.md').open('w') as f:
    f.write('\n'.join(summary_lines) + '\n')

print('Wrote /root/reagent_policy_report.json')
print('Wrote /root/reagent_policy_summary.md')
print(f'Decision: {decision}')
